        "evidenceOutput": "{'values_changed': {'root': {'new_value': {'0': 0, '1': -4, '2': -8, '3': -12, '4': -16, '5': -20, '6': -24, '7': -28, '8': -32, '9': -36, '10': -40, '11': -44}, 'old_value': {'0': 0, '1': 3}}}}\n{'values_changed': {'root': {'new_value': {'0': 0, '1': 3}, 'old_value': {}}}}\n{'values_changed': {'root': {'new_value': {}, 'old_value': {'0': 10, '1': 6, '2': 2, '3': -2, '4': -6, '5': -10, '6': -14, '7': -18, '8': -22, '9': -26, '10': -30, '11': -34}}}}",
